import http.cookiejar
import copy
from http.cookies import SimpleCookie, Morsel
from typing import Dict, Optional

class CookieUtils:
    @staticmethod
    def extract_cookies_to_jar(cookie_jar: http.cookiejar.CookieJar, response: 'http.client.HTTPResponse', request: 'urllib.request.Request') -> None:
        """Extract cookies from an HTTP response and add them to a cookie jar."""
        cookie_jar.extract_cookies(response, request)

    @staticmethod
    def get_cookie_header(cookie_jar: http.cookiejar.CookieJar, request: 'urllib.request.Request') -> str:
        """Return a cookie header string for a given request based on the cookie jar."""
        cookie_header = cookie_jar.make_cookie_header(request)
        return cookie_header

    @staticmethod
    def remove_cookie_by_name(cookie_jar: http.cookiejar.CookieJar, name: str, domain: Optional[str] = None, path: Optional[str] = None) -> None:
        """Remove a cookie from the cookie jar by name, optionally specifying domain and path."""
        for cookie in list(cookie_jar):
            if cookie.name == name and (domain is None or cookie.domain == domain) and (path is None or cookie.path == path):
                cookie_jar.clear(domain, path, name)

    @staticmethod
    def cookiejar_from_dict(cookie_dict: Dict[str, str], domain: str) -> http.cookiejar.CookieJar:
        """Create a cookie jar from a dictionary of cookie name-value pairs."""
        cookie_jar = http.cookiejar.CookieJar()
        for name, value in cookie_dict.items():
            cookie = CookieUtils.create_cookie(name, value, domain)
            cookie_jar.set_cookie(cookie)
        return cookie_jar

    @staticmethod
    def merge_cookies(cookie_jar1: http.cookiejar.CookieJar, cookie_jar2: http.cookiejar.CookieJar) -> http.cookiejar.CookieJar:
        """Merge two cookie jars into a new cookie jar."""
        merged_cookie_jar = http.cookiejar.CookieJar()
        for cookie in cookie_jar1:
            merged_cookie_jar.set_cookie(cookie)
        for cookie in cookie_jar2:
            merged_cookie_jar.set_cookie(cookie)
        return merged_cookie_jar

    @staticmethod
    def _copy_cookie_jar(cookie_jar: http.cookiejar.CookieJar) -> http.cookiejar.CookieJar:
        """Create a deep copy of a cookie jar."""
        return copy.deepcopy(cookie_jar)

    @staticmethod
    def create_cookie(name: str, value: str, domain: str, path: str = '/', secure: bool = False, expires: Optional[int] = None) -> http.cookiejar.Cookie:
        """Create a new cookie with the specified parameters."""
        return http.cookiejar.Cookie(
            version=0,
            name=name,
            value=value,
            port=None,
            port_specified=False,
            domain=domain,
            domain_specified=True,
            domain_initial_dot=domain.startswith('.'),
            path=path,
            path_specified=True,
            secure=secure,
            expires=expires,
            discard=False,
            comment=None,
            comment_url=None,
            rest={'HttpOnly': None},
            rfc2109=False
        )

    @staticmethod
    def morsel_to_cookie(morsel: Morsel) -> http.cookiejar.Cookie:
        """Convert a Morsel object to a Cookie object."""
        cookie = SimpleCookie()
        cookie[morsel.key] = morsel.value
        cookie_list = list(cookie.values())
        return http.cookiejar.Cookie(
            version=0,
            name=cookie_list[0].key,
            value=cookie_list[0].value,
            port=None,
            port_specified=False,
            domain=cookie_list[0]['domain'],
            domain_specified=cookie_list[0]['domain'] is not None,
            domain_initial_dot=cookie_list[0]['domain'].startswith('.') if cookie_list[0]['domain'] else False,
            path=cookie_list[0]['path'],
            path_specified=cookie_list[0]['path'] is not None,
