def recursive_diff(d1, d2, log=False):
    if d1 == d2:
        if log:
            print("Base case: dictionaries are equal")
        return False
    if not isinstance(d1, dict) or not isinstance(d2, dict):
        if log:
            print(f"Base case: one of the inputs is not a dictionary - {d1}, {d2}")
        return True
    diff = {}
    all_keys = set(d1.keys()).union(d2.keys())
    for key in all_keys:
        if key not in d1:
            diff[key] = f"Only in d2: {d2[key]}"
            if log:
                print(f"Key {key} only in d2")
        elif key not in d2:
            diff[key] = f"Only in d1: {d1[key]}"
            if log:
                print(f"Key {key} only in d1")
        else:
            sub_diff = recursive_diff(d1[key], d2[key], log)
            if sub_diff:
                diff[key] = sub_diff
    return diff

