def xmliter(obj, nodename, log=True):
    """Return an iterator over all nodes with the given name under the
    given object. `obj` can be either a string or a L{xml.dom.Node} object.
    """
    if log:
        logger.debug("Starting xmliter for node: %s", nodename)
    if isinstance(obj, str):
        obj = to_bytes(obj)
        try:
            from lxml import etree
            obj = etree.fromstring(obj)
        except ImportError:
            import xml.dom.minidom
            obj = xml.dom.minidom.parseString(obj)
            return obj.getElementsByTagName(nodename)
    if hasattr(obj, 'getiterator'):
        # handle lxml case
        for el in obj.getiterator():
            if el.tag == nodename:
                yield el
    else:
        # handle xml.dom.minidom case
        for el in obj.getElementsByTagName(nodename):
            yield el

