def load_translations(path=None):
    if path is None:
        path = os.path.join(os.path.dirname(__file__), "locale_data")
    for filename in os.listdir(path):
        if filename.endswith(".json"):
            with open(os.path.join(path, filename), "r", encoding="utf-8") as f:
                locale_code = filename[:-5]
                _LOCALE_DATA[locale_code] = json.load(f)

def get_translation(locale, key):
    return _LOCALE_DATA.get(locale, {}).get("translate", {}).get(key, key)

# Example usage
