from tornado.ioloop import IOLoop
from tornado import gen
import socket

class Resolver(object):
    def close(self):
        pass

    def resolve(self, host, port, family=0):
        raise NotImplementedError()

    def get_host_addresses(self, host, family=0):
        raise NotImplementedError()

class BlockingResolver(Resolver):
    def resolve(self, host, port, family=0):
        return socket.getaddrinfo(host, port, family)

    def get_host_addresses(self, host, family=0):
        return [addr[4][0] for addr in socket.getaddrinfo(host, None, family)]

class ThreadedResolver(Resolver):
    def __init__(self, io_loop=None):
        self.io_loop = io_loop or IOLoop.current()
        self.executor = self.io_loop.run_in_executor

    @gen.coroutine
    def resolve(self, host, port, family=0):
        result = yield self.executor(socket.getaddrinfo, host, port, family)
        raise gen.Return(result)

    @gen.coroutine
    def get_host_addresses(self, host, family=0):
        result = yield self.executor(socket.getaddrinfo, host, None, family)
        raise gen.Return([addr[4][0] for addr in result])

