class TCPClient(object):
    def __init__(self, resolver=None, io_loop=None):
        self.io_loop = io_loop or IOLoop.current()
        self.resolver = resolver or ThreadedResolver(io_loop=self.io_loop)

    def close(self):
        self.resolver.close()

    @gen.coroutine
    def connect(self, host, port, af=socket.AF_UNSPEC, ssl_options=None,
                 max_buffer_size=None, source_ip=None, source_port=None,
                 timeout=None, interface=None):
        addrinfo = yield self.resolver.resolve(host, port, af)
        stream = None
        for res in addrinfo:
            family, socktype, proto, canonname, sockaddr = res
            try:
                sock = socket.socket(family, socktype, proto)
                if source_ip:
                    sock.bind((source_ip, source_port or 0))
                if interface:
                    sock.setsockopt(socket.SOL_SOCKET, socket.SO_BINDTODEVICE, interface)
                if timeout is not None:
                    sock.settimeout(timeout)
                sock.connect(sockaddr)
                if ssl_options is not None:
                    stream = SSLIOStream(sock, ssl_options=ssl_options, io_loop=self.io_loop)
                else:
                    stream = IOStream(sock, io_loop=self.io_loop)
                stream.set_max_buffer_size(max_buffer_size)
                break
            except socket.error as e:
                if stream is not None:
                    stream.close()
                if e.errno in (socket.ECONNREFUSED, socket.ETIMEDOUT, socket.EHOSTUNREACH):
                    continue
                raise
        else:
            raise socket.error("Socket error during connection")
        raise gen.Return(stream)

